import { randomUUID } from "node:crypto";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { boundary, usageFixture, usageOwner } from "./fixtures/usage-worker";
import { databaseTestsEnabled } from "./helpers/foundation-db";
import { discoverAccountMaintenance } from "@/lib/inngest";
import { DELETION_RETENTION_MS } from "@/lib/account";
import { cleanupAttachments } from "@/lib/storage";

describe.runIf(databaseTestsEnabled)("daily cleanup discovery", () => {
  let fixture: Awaited<ReturnType<typeof usageFixture>>;
  const now = new Date("2026-10-20T03:00:00Z");
  const deadline = new Date(+now - DELETION_RETENTION_MS);

  beforeEach(async () => {
    fixture = await usageFixture();
    vi.stubEnv("BLOB_READ_WRITE_TOKEN", "");
    vi.stubEnv("NODE_ENV", "test");
  });
  afterEach(async () => {
    vi.unstubAllEnvs();
    if (fixture) await fixture.close();
  });

  async function attachment(userId: string, deletedAt: Date | null = null) {
    return boundary.db.attachment.create({
      data: {
        userId,
        fileName: "resume.pdf",
        storagePath: `resumes/${userId}/${randomUUID()}.pdf`,
        deletedAt,
      },
    });
  }

  it("skips idle accounts and finds eligible users beyond the first 100", async () => {
    const ids = Array.from({ length: 205 }, () => randomUUID()).sort();
    await boundary.db.user.createMany({
      data: ids.map((id) => ({ id, email: `${id}@example.test` })),
    });
    expect(await discoverAccountMaintenance()).toEqual([]);
    await attachment(ids[100]);
    await attachment(ids[204]);
    expect(await discoverAccountMaintenance()).toEqual([ids[100], ids[204]]);
  });

  it("leaves all deletion requests to the daily deletion job, including those with unused files", async () => {
    const due = await usageOwner(boundary.db);
    const early = await usageOwner(boundary.db);
    const recent = await usageOwner(boundary.db);
    for (const [owner, requestedAt] of [
      [due, deadline],
      [early, new Date(+deadline + 1)],
      [recent, now],
    ] as const) {
      await boundary.db.user.update({
        where: { id: owner.user.id },
        data: { deletionRequestedAt: requestedAt },
      });
      await attachment(owner.user.id);
    }
    expect(await discoverAccountMaintenance()).toEqual([]);
  });

  it("preserves current and protected send attachments while retrying unfinished physical deletions", async () => {
    const current = await usageOwner(boundary.db);
    const currentFile = await attachment(current.user.id);
    await boundary.db.user.update({
      where: { id: current.user.id },
      data: { currentAttachmentId: currentFile.id },
    });
    const completed = await usageOwner(boundary.db);
    const completedFile = await attachment(completed.user.id, now);
    await boundary.db.attachment.update({
      where: { id: completedFile.id, userId: completed.user.id },
      data: { storageDeletedAt: now },
    });
    const retry = await usageOwner(boundary.db);
    await attachment(retry.user.id, now);

    const eligible = [retry.user.id];
    for (const [status, deliveryState, pending] of [
      ["QUEUED", "READY", false],
      ["FAILED", "ATTEMPTING", false],
      ["FAILED", "UNCERTAIN", false],
      ["SENT", "DONE", true],
      ["CANCELLED", "DONE", true],
    ] as const) {
      const owner = await usageOwner(boundary.db);
      const file = await attachment(owner.user.id);
      const input = await owner.input();
      await boundary.db.campaign.create({
        data: {
          userId: owner.user.id,
          templateId: owner.template.id,
          status: pending ? "COMPLETED" : "QUEUED",
          attachmentId: file.id,
          sends: {
            create: { contactId: input.recipientIds[0], status, deliveryState },
          },
        },
      });
      if (pending) eligible.push(owner.user.id);
      // The worker's final check must agree with discovery, even on stale events.
      if (!pending) {
        await cleanupAttachments(owner.user.id);
        expect(
          await boundary.db.attachment.findFirst({
            where: { id: file.id, userId: owner.user.id },
          }),
        ).toMatchObject({ deletedAt: null, storageDeletedAt: null });
      }
    }
    expect(await discoverAccountMaintenance()).toEqual(eligible.sort());
    await cleanupAttachments(current.user.id);
    expect(
      await boundary.db.attachment.findFirst({
        where: { id: currentFile.id, userId: current.user.id },
      }),
    ).toMatchObject({ deletedAt: null, storageDeletedAt: null });
  });

  it("continues a backlog on later daily passes and stops scheduling completed work", async () => {
    const owner = await usageOwner(boundary.db);
    for (let index = 0; index < 12; index++)
      await attachment(owner.user.id, now);
    expect(await discoverAccountMaintenance()).toEqual([owner.user.id]);
    await cleanupAttachments(owner.user.id);
    expect(
      await boundary.db.attachment.count({
        where: { userId: owner.user.id, storageDeletedAt: { not: null } },
      }),
    ).toBe(10);
    expect(await discoverAccountMaintenance()).toEqual([owner.user.id]);
    await cleanupAttachments(owner.user.id);
    expect(
      await boundary.db.attachment.count({
        where: { userId: owner.user.id, storageDeletedAt: { not: null } },
      }),
    ).toBe(12);
    expect(await discoverAccountMaintenance()).toEqual([]);
  });
});
